CREATE TABLE "bills_of_material"("id" SERIAL PRIMARY KEY,"name" TEXT NOT NULL,"code" TEXT NOT NULL UNIQUE,"output_product_id" INTEGER NOT NULL REFERENCES "products"("id"),"yield_quantity" DOUBLE PRECISION NOT NULL DEFAULT 1,"active" BOOLEAN NOT NULL DEFAULT true,"notes" TEXT,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),"updated_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "bills_of_material_active_name_idx" ON "bills_of_material"("active","name");
CREATE TABLE "bill_of_material_items"("id" SERIAL PRIMARY KEY,"bom_id" INTEGER NOT NULL REFERENCES "bills_of_material"("id") ON DELETE CASCADE,"product_id" INTEGER NOT NULL REFERENCES "products"("id"),"quantity" DOUBLE PRECISION NOT NULL,"waste_percent" DOUBLE PRECISION NOT NULL DEFAULT 0,UNIQUE("bom_id","product_id"));
CREATE TABLE "production_orders"("id" SERIAL PRIMARY KEY,"number" TEXT NOT NULL UNIQUE,"bom_id" INTEGER NOT NULL REFERENCES "bills_of_material"("id"),"output_product_id" INTEGER NOT NULL REFERENCES "products"("id"),"warehouse_id" INTEGER NOT NULL REFERENCES "warehouses"("id"),"planned_quantity" DOUBLE PRECISION NOT NULL,"produced_quantity" DOUBLE PRECISION,"status" TEXT NOT NULL DEFAULT 'planned',"actual_cost" DOUBLE PRECISION,"notes" TEXT,"created_by" TEXT NOT NULL,"completed_at" TIMESTAMPTZ,"created_at" TIMESTAMPTZ NOT NULL DEFAULT now());CREATE INDEX "production_orders_status_created_at_idx" ON "production_orders"("status","created_at");
